// TH16 v1.00a bullet aliases used by this card (approved 0-43 slot reuse).
const TH16_BALL2: int = 432;
const TH16_RICE: int = 480;

// TH16 v1.00a Stage 1 wave 6.
// Source: st01.ecl.txt MainSub06:1311-1326 (entry), Cir00/Cir00_at:6-57,
// GirlC02/GirlC02_at:591-663, MainSub06b:1328-1337.

const TIME_LIMIT: int = 2924;
const OPENING_BUFFER: int = 120;

// Cir00 ellipse (st01.ecl.txt:14-15): omega 0.034906585 rad/frame = 2 deg/frame,
// axis snapshot = ABS angle 2.7488935 rad = 157.5 deg, jitter 0.17453292 rad = 10 deg.
const CIR_AXIS_BAM: int = 28672;
const CIR_AXIS_JITTER_BAM: int = 1820;
const CIR_OMEGA_BAM: int = 364;
const CIRCLE_RADIUS: fx = 10fx;
const CIR_SPEED: fx = 3fx;

// st01.ecl.txt:6-26. Position = ABS velocity 3px/frame at beta plus the REL
// ellipse (s=0: perpendicular sin offset of amplitude 10, period 180 frames).
async sub cir00(y0: fx, mirror: int) {
    set_invuln(65535);
    set_hurtbox(14fx); // setHurtbox(28,28)
    set_hitbox(8fx);   // setHitbox(16,16)

    var r2: int = rand(65536) - 32768; // RANDF2 in [-1,1)
    var beta: angle = (CIR_AXIS_BAM + r2 * CIR_AXIS_JITTER_BAM / 32768) as angle;
    var cs: fx = cos(beta);
    var sn: fx = sin(beta);
    var x0: fx = 224fx;
    var sign: fx = 1fx;
    if mirror != 0 { // enmCreateMF child mirror bit: whole trajectory reflected in x
        x0 = -224fx;
        sign = -1fx;
    }

    // !NHL: @Cir00_at() async
    if global(GVAR_RANK) >= 2 { spawn cir00_at(); }

    var t: int = 0;
    loop {
        var phase: angle = (t * CIR_OMEGA_BAM - (beta as int)) as angle;
        var rel: fx = CIRCLE_RADIUS * sin(phase);
        var ax: fx = CIR_SPEED * cs * (t as fx);
        var ay: fx = CIR_SPEED * sn * (t as fx);
        move_to(0, x0 + sign * (ax - rel * sn), y0 + ay + rel * cs, EASE_LINEAR);
        wait(1);
        t = t + 1;
        // Harness has no enemy offscreen cull; retire the source enemy once it is
        // well outside the field (its Cir00_at task has already ended).
        if $self_x < -320fx || $self_x > 320fx { break; }
        if $self_y > 560fx { break; }
    }
}

// st01.ecl.txt:28-57. mode0 aimed fan, N=1 => straight at player from the muzzle.
async sub cir00_at() {
    var r: int = global(GVAR_RANK);
    // !E/!N: 10+RAND%200; !H/!LO: 10+RAND%10
    var init_wait: int = 0;
    if r >= 2 { init_wait = 10 + rand(10); } else { init_wait = 10 + rand(200); }
    wait(init_wait);

    // etSprite(0,5,4) -> TH16_BALL2 color 4.
    // etCountD: N=1 always, layers=2 only on Lunatic.
    // etSpeedD: s0 = 1/1/3/4 by difficulty, s1 = 1 (M=1 uses s0 only).
    // diffI(A,1,1,2,3) -> burst count.
    var layers: int = 1;
    var speed0: fx = 1fx;
    var speed1: fx = 1fx;
    var bursts: int = 1;
    if r == 2 { speed0 = 3fx; bursts = 2; }
    if r >= 3 { speed0 = 4fx; layers = 2; bursts = 3; }

    var fired: int = 0;
    while fired < bursts {
        var a: angle = aim_player();
        var c: fx = cos(a);
        var s: fx = sin(a);
        var j: int = 0;
        while j < layers {
            var v: fx = speed0;
            if layers > 1 { v = speed0 + (speed1 - speed0) * (j as fx) / ((layers - 1) as fx); }
            // EX ANIM a=1: birth recoil position -= 4*velocity.
            _ = fire(TH16_BALL2, 4, $self_x - 4fx * v * c, $self_y - 4fx * v * s, v, a, none, none);
            j = j + 1;
        }
        wait(40);
        fired = fired + 1;
    }
}

// st01.ecl.txt:617-663.
async sub girl_c02_at() {
    var r: int = global(GVAR_RANK);
    // etCount: N=1, layers 4 (E) / 8 (N,H,L); etSpeed s0 = 1.6/2.6/3.4/2.6, s1 = 1.
    // diffI(B,1,2,4,12); burst gap 60/120/90/20.
    var layers: int = 8;
    var speed0: fx = 2.6fx;
    var speed1: fx = 1fx;
    var bursts: int = 12;
    var gap: int = 20;
    if r == 0 { layers = 4; speed0 = 1.6fx; bursts = 1; gap = 60; }
    if r == 1 { speed0 = 2.6fx; bursts = 2; gap = 120; }
    if r == 2 { speed0 = 3.4fx; bursts = 4; gap = 90; }
    wait(60);

    var fired: int = 0;
    while fired < bursts {
        var a: angle = aim_player();
        var c: fx = cos(a);
        var s: fx = sin(a);
        var j: int = 0;
        while j < layers {
            var v: fx = speed0;
            if layers > 1 { v = speed0 + (speed1 - speed0) * (j as fx) / ((layers - 1) as fx); }
            // EX ANIM a=1: birth recoil position -= 4*velocity.
            _ = fire(TH16_RICE, 6, $self_x - 4fx * v * c, $self_y - 4fx * v * s, v, a, none, none);
            j = j + 1;
        }
        wait(gap);
        fired = fired + 1;
    }
}

// st01.ecl.txt:591-615. FINAL_X = -96 <= 0, so moveSetMirror(1) is skipped.
async sub girl_c02() {
    set_invuln(65535);
    set_hurtbox(16fx); // setHurtbox(32,32)
    set_hitbox(12fx);  // setHitbox(24,24)
    move_vel(0, 90deg, 2fx, EASE_LINEAR);
    move_vel(80, 78.75deg, 1fx, EASE_QUAD_IN); // moveVelTime(80, mode1, 1.3744467f, 1.0f)
    spawn girl_c02_at();
    wait(60);
    while $self_y < 560fx { wait(1); }
}

// st01.ecl.txt:1328-1337.
async sub girl_wave() {
    wait(300);
    _ = spawn_enemy(-96fx, -32fx, 800, 0, 0, 0, girl_c02);
    wait(300);
    _ = spawn_enemy(-96fx, -32fx, 800, 0, 0, 0, girl_c02);
    wait(300);
    _ = spawn_enemy(-96fx, -32fx, 800, 0, 0, 0, girl_c02);
}

// st01.ecl.txt:1311-1326: 60 rounds, 22 frames apart; Hard/Lunatic get the mirror.
async sub pattern() {
    wait(OPENING_BUFFER);
    spawn girl_wave();
    var left: int = 60;
    while left > 0 {
        var u: fx = (rand(32768) as fx) / 32768; // RANDF in [0,1)
        var y: fx = 224fx * u - 48fx;
        _ = spawn_enemy(224fx, y, 60, 0, 0, 0, cir00(y, 0));
        if global(GVAR_RANK) >= 2 {
            var u2: fx = (rand(32768) as fx) / 32768;
            var y2: fx = 224fx * u2 - 48fx;
            _ = spawn_enemy(-224fx, y2, 60, 0, 0, 0, cir00(y2, 1));
        }
        wait(22);
        left = left - 1;
    }
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
